-- Migration 013: ESSA SLA policies, calendars, runtime clocks, audit.
-- Schema only — no INSERT. Policies and calendars are created via the admin UI.

CREATE TABLE IF NOT EXISTS "ESSA_SLA_CALENDAR" (
  "Id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "Code" VARCHAR(80) NOT NULL,
  "Name" VARCHAR(200) NOT NULL,
  "Timezone" VARCHAR(80) NOT NULL,
  "WorkingDays" VARCHAR(50) NOT NULL,
  "WorkStart" VARCHAR(5) NOT NULL,
  "WorkEnd" VARCHAR(5) NOT NULL,
  "Status" VARCHAR(20) NOT NULL,
  "Version" INTEGER NOT NULL DEFAULT 1,
  "EffectiveFrom" DATE NULL,
  "ExceptionsJson" TEXT NOT NULL DEFAULT '[]',
  "IsDeleted" BOOLEAN NOT NULL DEFAULT FALSE,
  "ChangedBy" VARCHAR(200) NULL,
  "ChangedAt" TIMESTAMP NULL,
  "CreatedDt" TIMESTAMP NOT NULL DEFAULT NOW(),
  "CreatedBy" INTEGER NULL,
  "ModifiedDt" TIMESTAMP NULL,
  "ModifiedBy" INTEGER NULL
);

CREATE INDEX IF NOT EXISTS "IX_ESSA_SLA_CALENDAR_Status"
  ON "ESSA_SLA_CALENDAR" ("Status", "IsDeleted");

CREATE TABLE IF NOT EXISTS "ESSA_SLA_POLICY" (
  "Id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "Code" VARCHAR(80) NOT NULL,
  "Name" VARCHAR(200) NOT NULL,
  "Description" VARCHAR(500) NULL,
  "ScopeType" VARCHAR(40) NOT NULL,
  "Activity" VARCHAR(40) NULL,
  "Stage" VARCHAR(40) NOT NULL,
  "TriggerEvent" VARCHAR(40) NOT NULL,
  "Owner" VARCHAR(40) NOT NULL,
  "Provisional" BOOLEAN NOT NULL DEFAULT FALSE,
  "ProvisionalNote" TEXT NULL,
  "Version" INTEGER NOT NULL DEFAULT 1,
  "Status" VARCHAR(20) NOT NULL,
  "EffectiveFrom" DATE NULL,
  "TimerJson" TEXT NOT NULL,
  "RemindersJson" TEXT NOT NULL DEFAULT '[]',
  "EscalationJson" TEXT NOT NULL,
  "PauseRulesJson" TEXT NOT NULL DEFAULT '[]',
  "ManualPauseAllowed" BOOLEAN NOT NULL DEFAULT TRUE,
  "MaxPauseJson" TEXT NULL,
  "PublishedBy" VARCHAR(200) NULL,
  "PublishedAt" TIMESTAMP NULL,
  "ChangedBy" VARCHAR(200) NULL,
  "ChangedAt" TIMESTAMP NULL,
  "IsDeleted" BOOLEAN NOT NULL DEFAULT FALSE,
  "CreatedDt" TIMESTAMP NOT NULL DEFAULT NOW(),
  "CreatedBy" INTEGER NULL,
  "ModifiedDt" TIMESTAMP NULL,
  "ModifiedBy" INTEGER NULL
);

CREATE UNIQUE INDEX IF NOT EXISTS "UX_ESSA_SLA_POLICY_Code_Version"
  ON "ESSA_SLA_POLICY" ("Code", "Version")
  WHERE "IsDeleted" = FALSE;

CREATE INDEX IF NOT EXISTS "IX_ESSA_SLA_POLICY_Lookup"
  ON "ESSA_SLA_POLICY" ("Status", "Stage", "ScopeType", "Activity", "IsDeleted");

CREATE TABLE IF NOT EXISTS "ESSA_SLA_INSTANCE" (
  "Id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "ObjectType" VARCHAR(40) NOT NULL,
  "ObjectId" VARCHAR(80) NOT NULL,
  "Reference" VARCHAR(80) NULL,
  "InvoiceNumber" VARCHAR(80) NULL,
  "VendorName" VARCHAR(250) NULL,
  "CategoryId" VARCHAR(40) NULL,
  "CategoryName" VARCHAR(80) NULL,
  "PolicyId" INTEGER NOT NULL,
  "PolicyCode" VARCHAR(80) NOT NULL,
  "PolicyName" VARCHAR(200) NOT NULL,
  "Stage" VARCHAR(40) NOT NULL,
  "Owner" VARCHAR(80) NOT NULL,
  "StartedAt" TIMESTAMP NOT NULL,
  "DueAt" TIMESTAMP NULL,
  "WarningAt" TIMESTAMP NULL,
  "Status" VARCHAR(20) NOT NULL,
  "FrozenRemainingMs" BIGINT NULL,
  "Note" VARCHAR(500) NULL,
  "PauseStartedAt" TIMESTAMP NULL,
  "PauseUsedMs" BIGINT NOT NULL DEFAULT 0,
  "EventsJson" TEXT NOT NULL DEFAULT '[]',
  "RemindersSentJson" TEXT NOT NULL DEFAULT '[]',
  "EscalatedAt" TIMESTAMP NULL,
  "CalendarId" INTEGER NULL,
  "InvoiceId" INTEGER NULL,
  "IsDeleted" BOOLEAN NOT NULL DEFAULT FALSE,
  "CreatedDt" TIMESTAMP NOT NULL DEFAULT NOW(),
  "ModifiedDt" TIMESTAMP NULL
);

CREATE INDEX IF NOT EXISTS "IX_ESSA_SLA_INSTANCE_Object"
  ON "ESSA_SLA_INSTANCE" ("ObjectType", "ObjectId", "Status", "IsDeleted");
CREATE INDEX IF NOT EXISTS "IX_ESSA_SLA_INSTANCE_Policy"
  ON "ESSA_SLA_INSTANCE" ("PolicyId", "Status");

CREATE TABLE IF NOT EXISTS "ESSA_SLA_AUDIT" (
  "Id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "EntityType" VARCHAR(40) NOT NULL,
  "EntityId" INTEGER NOT NULL,
  "Action" VARCHAR(40) NOT NULL,
  "Detail" TEXT NULL,
  "Actor" VARCHAR(200) NULL,
  "ActorUserId" INTEGER NULL,
  "CreatedDt" TIMESTAMP NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS "IX_ESSA_SLA_AUDIT_Entity"
  ON "ESSA_SLA_AUDIT" ("EntityType", "EntityId", "CreatedDt" DESC);

ALTER TABLE "ESSA_SLA_POLICY" ADD COLUMN IF NOT EXISTS "ProvisionalNote" TEXT NULL;
